public final class Circle {
    private final double radius;
    private final List<Item> items;

    public Circle(double radius, List<Item> items) {
        this.radius = radius;
        this.items = List.copyOf(items);   // defensive copy
    }
    public double radius() { return radius; }
    public List<Item> items() { return items; }   // unmodifiable
}

public record CircleData(double radius, List<Item> items) {
    public CircleData {                       // compact canonical constructor
        if (radius < 0) throw new IllegalArgumentException("radius");
        items = List.copyOf(items);           // defensive copy
    }
}

